const explanationCache = new Map(), explanationInFlight = new Map(), explanationState = new Map();
const careTranslationCache = new Map(), careTranslationRuns = new Map();
const careExtraLanguages = { kn: 'Kannada', ta: 'Tamil', bn: 'Bengali', te: 'Telugu', mr: 'Marathi' };
const $ = (s, root = document) => root.querySelector(s), $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
